WITH with_dims AS (SELECT e.*, p.opened_date FROM inventory e LEFT JOIN stores p ON e.store_id = p.id) SELECT DATE_TRUNC('QUARTER', last_restock) AS quarter_start, STDDEV_SAMP(quantity) AS quantity_stddev, SUM(quantity) AS total_quantity, APPROX_PERCENTILE(quantity, 0.9) AS quantity_p90, COUNT(DISTINCT product_id) AS distinct_product_ids FROM with_dims GROUP BY DATE_TRUNC('QUARTER', last_restock) HAVING APPROX_PERCENTILE(quantity, 0.9) < 0 ORDER BY quantity_p90 DESC NULLS LAST;
